// Simple client-side password gate. The password itself is never committed —
// only its SHA-256 hash (generated by the workflow from the PAGE_PASSWORD
// secret) is fetched and compared here.
//
// Note: this hides the dashboard UI from casual visitors, but GitHub Pages
// serves every file publicly with no per-file access control, so the raw
// data/*.json files remain fetchable by direct URL regardless of this gate.
(async function () {
  const SESSION_KEY = "proxy-monitor-unlocked";
  const lock = document.getElementById("lock");
  const app = document.getElementById("app");
  const form = document.getElementById("lock-form");
  const input = document.getElementById("lock-pass");
  const err = document.getElementById("lock-error");

  async function sha256Hex(text) {
    const buf = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(text));
    return Array.from(new Uint8Array(buf)).map((b) => b.toString(16).padStart(2, "0")).join("");
  }

  function unlock() {
    lock.classList.add("hidden");
    app.hidden = false;
    if (window.startDashboard) window.startDashboard();
  }

  let expectedHash = null;
  try {
    const r = await fetch("data/lock-hash.json?_=" + Date.now(), { cache: "no-store" });
    if (r.ok) expectedHash = (await r.json()).hash || null;
  } catch { /* treated as not-configured below */ }

  if (expectedHash && sessionStorage.getItem(SESSION_KEY) === expectedHash) {
    unlock();
    return;
  }

  form.addEventListener("submit", async (e) => {
    e.preventDefault();
    if (!expectedHash) {
      err.textContent = "Lock not configured yet — set PAGE_PASSWORD and run the workflow once.";
      return;
    }
    const hash = await sha256Hex(input.value);
    if (hash === expectedHash) {
      sessionStorage.setItem(SESSION_KEY, expectedHash);
      unlock();
    } else {
      err.textContent = "Incorrect password.";
      input.value = "";
      input.focus();
    }
  });
})();
